/**
 * FreeLang Frontend Generator
 * 프리랭으로 완전한 블로그 프론트엔드 생성
 *
 * 목표:
 * 1. HTML 완전 생성 (구조)
 * 2. CSS 완전 생성 (스타일)
 * 3. JavaScript 완전 생성 (동작)
 * 4. API 통합 (백엔드 연결)
 * 5. 상태 관리 (클라이언트 사이드)
 */

module FrontendGenerator {

  // ============================================================================
  // Part 1: Configuration & Types
  // ============================================================================

  struct BlogConfig {
    title: string,
    api_url: string,
    port: i32,
    theme: string,
    auto_refresh: i32,  // milliseconds
  }

  struct UIState {
    current_page: i32,
    posts_per_page: i32,
    theme: string,
    search_query: string,
    selected_category: string,
  }

  // ============================================================================
  // Part 2: HTML Generator
  // ============================================================================

  pub fn generate_complete_html(config: BlogConfig) -> string {
    let html = "<!DOCTYPE html>\n";
    html = html + "<html lang=\"ko\">\n";
    html = html + generate_head(config);
    html = html + generate_body(config);
    html = html + "</html>\n";
    return html;
  }

  fn generate_head(config: BlogConfig) -> string {
    let head = "<head>\n";
    head = head + "  <meta charset=\"UTF-8\">\n";
    head = head + "  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n";
    head = head + "  <title>" + config.title + "</title>\n";
    head = head + "  <style>\n";
    head = head + generate_complete_css(config);
    head = head + "  </style>\n";
    head = head + "</head>\n";
    return head;
  }

  fn generate_body(config: BlogConfig) -> string {
    let body = "<body>\n";
    body = body + "  <div id=\"app\" class=\"container\">\n";
    body = body + generate_navbar(config);
    body = body + generate_hero(config);
    body = body + generate_create_post_section(config);
    body = body + generate_filters(config);
    body = body + generate_posts_container();
    body = body + generate_modals();
    body = body + "  </div>\n";
    body = body + "  <script>\n";
    body = body + generate_complete_javascript(config);
    body = body + "  </script>\n";
    body = body + "</body>\n";
    return body;
  }

  fn generate_navbar(config: BlogConfig) -> string {
    let nav = "    <nav class=\"navbar\">\n";
    nav = nav + "      <div class=\"navbar-brand\">\n";
    nav = nav + "        <h1>📝 " + config.title + "</h1>\n";
    nav = nav + "        <p class=\"subtitle\">FreeLang으로 만든 완전한 블로그</p>\n";
    nav = nav + "      </div>\n";
    nav = nav + "      <div class=\"navbar-menu\">\n";
    nav = nav + "        <button class=\"theme-toggle\" onclick=\"toggleTheme()\">🌙</button>\n";
    nav = nav + "        <input type=\"text\" id=\"search\" placeholder=\"검색...\" onkeyup=\"searchPosts(this.value)\" class=\"search-box\">\n";
    nav = nav + "      </div>\n";
    nav = nav + "    </nav>\n";
    return nav;
  }

  fn generate_hero(config: BlogConfig) -> string {
    let hero = "    <section class=\"hero\">\n";
    hero = hero + "      <h2>FreeLang Blog Engine</h2>\n";
    hero = hero + "      <p>순수 프리랭으로 구현된 제로 디펜던시 블로그</p>\n";
    hero = hero + "      <div class=\"stats\">\n";
    hero = hero + "        <div class=\"stat\">📚 <span id=\"post-count\">0</span> 포스트</div>\n";
    hero = hero + "        <div class=\"stat\">❤️ <span id=\"total-likes\">0</span> 좋아요</div>\n";
    hero = hero + "        <div class=\"stat\">👁️ <span id=\"total-views\">0</span> 조회</div>\n";
    hero = hero + "      </div>\n";
    hero = hero + "    </section>\n";
    return hero;
  }

  fn generate_create_post_section(config: BlogConfig) -> string {
    let form = "    <section class=\"create-post\">\n";
    form = form + "      <h2>✍️ 새 포스트 작성</h2>\n";
    form = form + "      <form id=\"postForm\" onsubmit=\"handleCreatePost(event)\">\n";
    form = form + "        <div class=\"form-row\">\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"title\">제목</label>\n";
    form = form + "            <input type=\"text\" id=\"title\" required placeholder=\"포스트 제목\">\n";
    form = form + "          </div>\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"author\">작성자</label>\n";
    form = form + "            <input type=\"text\" id=\"author\" required placeholder=\"이름\">\n";
    form = form + "          </div>\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-row\">\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"category\">카테고리</label>\n";
    form = form + "            <input type=\"text\" id=\"category\" required placeholder=\"기술, 일상, ...\">\n";
    form = form + "          </div>\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"slug\">슬러그</label>\n";
    form = form + "            <input type=\"text\" id=\"slug\" required placeholder=\"url-friendly\">\n";
    form = form + "          </div>\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-group\">\n";
    form = form + "          <label for=\"description\">설명</label>\n";
    form = form + "          <input type=\"text\" id=\"description\" placeholder=\"포스트 한줄 설명\">\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-group\">\n";
    form = form + "          <label for=\"content\">내용</label>\n";
    form = form + "          <textarea id=\"content\" required placeholder=\"포스트 내용...\" rows=\"8\"></textarea>\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-group\">\n";
    form = form + "          <label for=\"tags\">태그 (쉼표 구분)</label>\n";
    form = form + "          <input type=\"text\" id=\"tags\" placeholder=\"tag1, tag2, tag3\">\n";
    form = form + "        </div>\n";
    form = form + "        <button type=\"submit\" class=\"btn-primary\">📤 포스트 작성</button>\n";
    form = form + "      </form>\n";
    form = form + "      <div id=\"message\" class=\"message\"></div>\n";
    form = form + "    </section>\n";
    return form;
  }

  fn generate_filters(config: BlogConfig) -> string {
    let filters = "    <section class=\"filters\">\n";
    filters = filters + "      <button class=\"filter-btn active\" onclick=\"filterPosts('all')\">📌 전체</button>\n";
    filters = filters + "      <button class=\"filter-btn\" onclick=\"filterPosts('Achievement')\">🏆 성과</button>\n";
    filters = filters + "      <button class=\"filter-btn\" onclick=\"filterPosts('Technical')\">⚙️ 기술</button>\n";
    filters = filters + "      <button class=\"filter-btn\" onclick=\"filterPosts('Architecture')\">🏗️ 아키텍처</button>\n";
    filters = filters + "    </section>\n";
    return filters;
  }

  fn generate_posts_container() -> string {
    return "    <section id=\"postsContainer\" class=\"posts-container\"></section>\n";
  }

  fn generate_modals() -> string {
    let modals = "    <div id=\"postModal\" class=\"modal\">\n";
    modals = modals + "      <div class=\"modal-content\">\n";
    modals = modals + "        <span class=\"modal-close\" onclick=\"closeModal()\">&times;</span>\n";
    modals = modals + "        <div id=\"modalBody\"></div>\n";
    modals = modals + "      </div>\n";
    modals = modals + "    </div>\n";
    return modals;
  }

  // ============================================================================
  // Part 3: CSS Generator
  // ============================================================================

  fn generate_complete_css(config: BlogConfig) -> string {
    let css = "* {\n";
    css = css + "  margin: 0;\n";
    css = css + "  padding: 0;\n";
    css = css + "  box-sizing: border-box;\n";
    css = css + "}\n\n";

    css = css + generate_base_styles();
    css = css + generate_navbar_styles();
    css = css + generate_hero_styles();
    css = css + generate_form_styles();
    css = css + generate_filter_styles();
    css = css + generate_post_card_styles();
    css = css + generate_modal_styles();
    css = css + generate_theme_styles();
    css = css + generate_responsive_styles();

    return css;
  }

  fn generate_base_styles() -> string {
    let css = "body {\n";
    css = css + "  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n";
    css = css + "  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n";
    css = css + "  color: #333;\n";
    css = css + "  min-height: 100vh;\n";
    css = css + "  transition: background 0.3s ease;\n";
    css = css + "}\n\n";

    css = css + "body.dark-theme {\n";
    css = css + "  background: linear-gradient(135deg, #2d3436 0%, #636e72 100%);\n";
    css = css + "  color: #fff;\n";
    css = css + "}\n\n";

    css = css + ".container {\n";
    css = css + "  max-width: 1200px;\n";
    css = css + "  margin: 0 auto;\n";
    css = css + "  padding: 20px;\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_navbar_styles() -> string {
    let css = ".navbar {\n";
    css = css + "  background: rgba(255, 255, 255, 0.95);\n";
    css = css + "  padding: 20px 30px;\n";
    css = css + "  border-radius: 10px;\n";
    css = css + "  margin-bottom: 30px;\n";
    css = css + "  display: flex;\n";
    css = css + "  justify-content: space-between;\n";
    css = css + "  align-items: center;\n";
    css = css + "  box-shadow: 0 10px 30px rgba(0,0,0,0.1);\n";
    css = css + "}\n\n";

    css = css + ".navbar-brand h1 {\n";
    css = css + "  color: #667eea;\n";
    css = css + "  font-size: 1.8em;\n";
    css = css + "}\n\n";

    css = css + ".subtitle {\n";
    css = css + "  color: #666;\n";
    css = css + "  font-size: 0.9em;\n";
    css = css + "}\n\n";

    css = css + ".navbar-menu {\n";
    css = css + "  display: flex;\n";
    css = css + "  gap: 15px;\n";
    css = css + "  align-items: center;\n";
    css = css + "}\n\n";

    css = css + ".search-box {\n";
    css = css + "  padding: 10px 15px;\n";
    css = css + "  border: 2px solid #eee;\n";
    css = css + "  border-radius: 5px;\n";
    css = css + "  width: 250px;\n";
    css = css + "}\n\n";

    css = css + ".theme-toggle {\n";
    css = css + "  background: #f0f0f0;\n";
    css = css + "  border: none;\n";
    css = css + "  padding: 8px 12px;\n";
    css = css + "  border-radius: 5px;\n";
    css = css + "  cursor: pointer;\n";
    css = css + "  font-size: 1.2em;\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_hero_styles() -> string {
    let css = ".hero {\n";
    css = css + "  background: rgba(255, 255, 255, 0.95);\n";
    css = css + "  padding: 60px;\n";
    css = css + "  border-radius: 10px;\n";
    css = css + "  text-align: center;\n";
    css = css + "  margin-bottom: 30px;\n";
    css = css + "  box-shadow: 0 10px 30px rgba(0,0,0,0.1);\n";
    css = css + "}\n\n";

    css = css + ".hero h2 {\n";
    css = css + "  color: #667eea;\n";
    css = css + "  font-size: 2.5em;\n";
    css = css + "  margin-bottom: 10px;\n";
    css = css + "}\n\n";

    css = css + ".hero p {\n";
    css = css + "  color: #666;\n";
    css = css + "  font-size: 1.1em;\n";
    css = css + "  margin-bottom: 30px;\n";
    css = css + "}\n\n";

    css = css + ".stats {\n";
    css = css + "  display: flex;\n";
    css = css + "  justify-content: center;\n";
    css = css + "  gap: 40px;\n";
    css = css + "}\n\n";

    css = css + ".stat {\n";
    css = css + "  font-size: 1.2em;\n";
    css = css + "  color: #333;\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_form_styles() -> string {
    let css = ".create-post {\n";
    css = css + "  background: rgba(255, 255, 255, 0.95);\n";
    css = css + "  padding: 30px;\n";
    css = css + "  border-radius: 10px;\n";
    css = css + "  margin-bottom: 30px;\n";
    css = css + "  box-shadow: 0 10px 30px rgba(0,0,0,0.1);\n";
    css = css + "}\n\n";

    css = css + ".create-post h2 {\n";
    css = css + "  color: #333;\n";
    css = css + "  margin-bottom: 20px;\n";
    css = css + "}\n\n";

    css = css + ".form-row {\n";
    css = css + "  display: grid;\n";
    css = css + "  grid-template-columns: 1fr 1fr;\n";
    css = css + "  gap: 20px;\n";
    css = css + "  margin-bottom: 20px;\n";
    css = css + "}\n\n";

    css = css + ".form-group {\n";
    css = css + "  margin-bottom: 20px;\n";
    css = css + "}\n\n";

    css = css + ".form-group label {\n";
    css = css + "  display: block;\n";
    css = css + "  margin-bottom: 8px;\n";
    css = css + "  font-weight: 600;\n";
    css = css + "  color: #333;\n";
    css = css + "}\n\n";

    css = css + ".form-group input,\n";
    css = css + ".form-group textarea {\n";
    css = css + "  width: 100%;\n";
    css = css + "  padding: 12px;\n";
    css = css + "  border: 2px solid #eee;\n";
    css = css + "  border-radius: 5px;\n";
    css = css + "  font-family: inherit;\n";
    css = css + "  font-size: 1em;\n";
    css = css + "  transition: border-color 0.3s;\n";
    css = css + "}\n\n";

    css = css + ".form-group input:focus,\n";
    css = css + ".form-group textarea:focus {\n";
    css = css + "  outline: none;\n";
    css = css + "  border-color: #667eea;\n";
    css = css + "}\n\n";

    css = css + ".btn-primary {\n";
    css = css + "  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n";
    css = css + "  color: white;\n";
    css = css + "  padding: 12px 30px;\n";
    css = css + "  border: none;\n";
    css = css + "  border-radius: 5px;\n";
    css = css + "  font-size: 1em;\n";
    css = css + "  cursor: pointer;\n";
    css = css + "  transition: transform 0.2s;\n";
    css = css + "}\n\n";

    css = css + ".btn-primary:hover {\n";
    css = css + "  transform: translateY(-2px);\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_filter_styles() -> string {
    let css = ".filters {\n";
    css = css + "  display: flex;\n";
    css = css + "  gap: 10px;\n";
    css = css + "  margin-bottom: 30px;\n";
    css = css + "  justify-content: center;\n";
    css = css + "  flex-wrap: wrap;\n";
    css = css + "}\n\n";

    css = css + ".filter-btn {\n";
    css = css + "  padding: 10px 20px;\n";
    css = css + "  border: 2px solid #667eea;\n";
    css = css + "  background: white;\n";
    css = css + "  color: #667eea;\n";
    css = css + "  border-radius: 20px;\n";
    css = css + "  cursor: pointer;\n";
    css = css + "  transition: all 0.3s;\n";
    css = css + "}\n\n";

    css = css + ".filter-btn.active {\n";
    css = css + "  background: #667eea;\n";
    css = css + "  color: white;\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_post_card_styles() -> string {
    let css = ".posts-container {\n";
    css = css + "  display: grid;\n";
    css = css + "  gap: 20px;\n";
    css = css + "}\n\n";

    css = css + ".post-card {\n";
    css = css + "  background: rgba(255, 255, 255, 0.95);\n";
    css = css + "  padding: 25px;\n";
    css = css + "  border-radius: 10px;\n";
    css = css + "  box-shadow: 0 10px 30px rgba(0,0,0,0.1);\n";
    css = css + "  transition: transform 0.3s, box-shadow 0.3s;\n";
    css = css + "}\n\n";

    css = css + ".post-card:hover {\n";
    css = css + "  transform: translateY(-5px);\n";
    css = css + "  box-shadow: 0 15px 40px rgba(0,0,0,0.15);\n";
    css = css + "}\n\n";

    css = css + ".post-header {\n";
    css = css + "  display: flex;\n";
    css = css + "  justify-content: space-between;\n";
    css = css + "  align-items: flex-start;\n";
    css = css + "  margin-bottom: 15px;\n";
    css = css + "}\n\n";

    css = css + ".post-title {\n";
    css = css + "  color: #333;\n";
    css = css + "  font-size: 1.5em;\n";
    css = css + "  margin-bottom: 8px;\n";
    css = css + "}\n\n";

    css = css + ".post-meta {\n";
    css = css + "  color: #999;\n";
    css = css + "  font-size: 0.9em;\n";
    css = css + "}\n\n";

    css = css + ".post-category {\n";
    css = css + "  display: inline-block;\n";
    css = css + "  background: #667eea;\n";
    css = css + "  color: white;\n";
    css = css + "  padding: 4px 12px;\n";
    css = css + "  border-radius: 20px;\n";
    css = css + "  font-size: 0.85em;\n";
    css = css + "  margin-bottom: 15px;\n";
    css = css + "}\n\n";

    css = css + ".post-content {\n";
    css = css + "  color: #555;\n";
    css = css + "  line-height: 1.6;\n";
    css = css + "  margin-bottom: 15px;\n";
    css = css + "}\n\n";

    css = css + ".post-stats {\n";
    css = css + "  display: flex;\n";
    css = css + "  gap: 20px;\n";
    css = css + "  margin-bottom: 15px;\n";
    css = css + "  font-size: 0.95em;\n";
    css = css + "  color: #666;\n";
    css = css + "}\n\n";

    css = css + ".post-actions {\n";
    css = css + "  display: flex;\n";
    css = css + "  gap: 10px;\n";
    css = css + "}\n\n";

    css = css + ".post-btn {\n";
    css = css + "  padding: 8px 15px;\n";
    css = css + "  border: none;\n";
    css = css + "  background: #f0f0f0;\n";
    css = css + "  color: #333;\n";
    css = css + "  border-radius: 5px;\n";
    css = css + "  cursor: pointer;\n";
    css = css + "  transition: background 0.3s;\n";
    css = css + "}\n\n";

    css = css + ".post-btn:hover {\n";
    css = css + "  background: #e0e0e0;\n";
    css = css + "}\n\n";

    css = css + ".post-btn-danger {\n";
    css = css + "  background: #ff6b6b;\n";
    css = css + "  color: white;\n";
    css = css + "}\n\n";

    css = css + ".post-btn-danger:hover {\n";
    css = css + "  background: #ff5252;\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_modal_styles() -> string {
    let css = ".modal {\n";
    css = css + "  display: none;\n";
    css = css + "  position: fixed;\n";
    css = css + "  z-index: 1000;\n";
    css = css + "  left: 0;\n";
    css = css + "  top: 0;\n";
    css = css + "  width: 100%;\n";
    css = css + "  height: 100%;\n";
    css = css + "  background-color: rgba(0,0,0,0.8);\n";
    css = css + "}\n\n";

    css = css + ".modal-content {\n";
    css = css + "  background: white;\n";
    css = css + "  margin: 5% auto;\n";
    css = css + "  padding: 40px;\n";
    css = css + "  border-radius: 10px;\n";
    css = css + "  width: 90%;\n";
    css = css + "  max-width: 900px;\n";
    css = css + "  max-height: 80vh;\n";
    css = css + "  overflow-y: auto;\n";
    css = css + "  box-shadow: 0 20px 60px rgba(0,0,0,0.3);\n";
    css = css + "}\n\n";

    css = css + ".modal-close {\n";
    css = css + "  float: right;\n";
    css = css + "  font-size: 2em;\n";
    css = css + "  font-weight: bold;\n";
    css = css + "  cursor: pointer;\n";
    css = css + "  color: #999;\n";
    css = css + "}\n\n";

    css = css + ".modal-close:hover {\n";
    css = css + "  color: #333;\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_theme_styles() -> string {
    let css = "body.dark-theme .navbar {\n";
    css = css + "  background: rgba(45, 52, 54, 0.95);\n";
    css = css + "}\n\n";

    css = css + "body.dark-theme .navbar-brand h1 {\n";
    css = css + "  color: #667eea;\n";
    css = css + "}\n\n";

    css = css + "body.dark-theme .hero,\n";
    css = css + "body.dark-theme .create-post,\n";
    css = css + "body.dark-theme .post-card {\n";
    css = css + "  background: rgba(45, 52, 54, 0.95);\n";
    css = css + "  color: #fff;\n";
    css = css + "}\n\n";

    css = css + "body.dark-theme .post-card {\n";
    css = css + "  border-left: 4px solid #667eea;\n";
    css = css + "}\n\n";

    css = css + "body.dark-theme .form-group input,\n";
    css = css + "body.dark-theme .form-group textarea {\n";
    css = css + "  background: #333;\n";
    css = css + "  color: #fff;\n";
    css = css + "  border-color: #555;\n";
    css = css + "}\n\n";

    return css;
  }

  fn generate_responsive_styles() -> string {
    let css = "@media (max-width: 768px) {\n";
    css = css + "  .form-row {\n";
    css = css + "    grid-template-columns: 1fr;\n";
    css = css + "  }\n\n";

    css = css + "  .navbar {\n";
    css = css + "    flex-direction: column;\n";
    css = css + "    gap: 15px;\n";
    css = css + "  }\n\n";

    css = css + "  .navbar-menu {\n";
    css = css + "    flex-direction: column;\n";
    css = css + "    width: 100%;\n";
    css = css + "  }\n\n";

    css = css + "  .search-box {\n";
    css = css + "    width: 100%;\n";
    css = css + "  }\n\n";

    css = css + "  .post-header {\n";
    css = css + "    flex-direction: column;\n";
    css = css + "  }\n\n";

    css = css + "}\n";
    return css;
  }

  // ============================================================================
  // Part 4: JavaScript Generator
  // ============================================================================

  fn generate_complete_javascript(config: BlogConfig) -> string {
    let js = "// FreeLang Generated Blog Frontend\n";
    js = js + "const API_URL = '" + config.api_url + "/api';\n";
    js = js + "const AUTO_REFRESH = " + to_string(config.auto_refresh) + ";\n\n";

    js = js + generate_state_management();
    js = js + generate_api_functions();
    js = js + generate_ui_functions();
    js = js + generate_event_handlers();
    js = js + generate_initialization();

    return js;
  }

  fn generate_state_management() -> string {
    let js = "// State Management\n";
    js = js + "let appState = {\n";
    js = js + "  posts: [],\n";
    js = js + "  filteredPosts: [],\n";
    js = js + "  currentFilter: 'all',\n";
    js = js + "  currentSearch: '',\n";
    js = js + "  isDarkTheme: localStorage.getItem('theme') === 'dark',\n";
    js = js + "  totalLikes: 0,\n";
    js = js + "  totalViews: 0\n";
    js = js + "};\n\n";

    return js;
  }

  fn generate_api_functions() -> string {
    let js = "// API Functions\n";
    js = js + "async function fetchPosts() {\n";
    js = js + "  try {\n";
    js = js + "    const res = await fetch(API_URL + '/blogs');\n";
    js = js + "    const data = await res.json();\n";
    js = js + "    appState.posts = data.data || [];\n";
    js = js + "    appState.totalLikes = appState.posts.reduce((sum, p) => sum + (p.likes || 0), 0);\n";
    js = js + "    appState.totalViews = appState.posts.reduce((sum, p) => sum + (p.viewCount || 0), 0);\n";
    js = js + "    applyFiltersAndSearch();\n";
    js = js + "    updateUI();\n";
    js = js + "  } catch (err) {\n";
    js = js + "    console.error('포스트 로드 오류:', err);\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function createPost(postData) {\n";
    js = js + "  try {\n";
    js = js + "    const res = await fetch(API_URL + '/blogs', {\n";
    js = js + "      method: 'POST',\n";
    js = js + "      headers: { 'Content-Type': 'application/json' },\n";
    js = js + "      body: JSON.stringify(postData)\n";
    js = js + "    });\n";
    js = js + "    if (res.ok) {\n";
    js = js + "      showMessage('✅ 포스트 작성됨!', 'success');\n";
    js = js + "      document.getElementById('postForm').reset();\n";
    js = js + "      fetchPosts();\n";
    js = js + "    } else {\n";
    js = js + "      showMessage('❌ 포스트 작성 실패', 'error');\n";
    js = js + "    }\n";
    js = js + "  } catch (err) {\n";
    js = js + "    showMessage('❌ 오류: ' + err.message, 'error');\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function likePost(postId) {\n";
    js = js + "  try {\n";
    js = js + "    await fetch(API_URL + '/blogs/' + postId + '/like', { method: 'POST' });\n";
    js = js + "    fetchPosts();\n";
    js = js + "  } catch (err) {\n";
    js = js + "    console.error('좋아요 오류:', err);\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function viewPost(postId) {\n";
    js = js + "  try {\n";
    js = js + "    await fetch(API_URL + '/blogs/' + postId + '/view', { method: 'POST' });\n";
    js = js + "    fetchPosts();\n";
    js = js + "  } catch (err) {\n";
    js = js + "    console.error('조회수 증가 오류:', err);\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function deletePost(postId) {\n";
    js = js + "  if (confirm('정말 삭제하시겠습니까?')) {\n";
    js = js + "    try {\n";
    js = js + "      await fetch(API_URL + '/blogs/' + postId, { method: 'DELETE' });\n";
    js = js + "      showMessage('✅ 포스트 삭제됨!', 'success');\n";
    js = js + "      closeModal();\n";
    js = js + "      fetchPosts();\n";
    js = js + "    } catch (err) {\n";
    js = js + "      showMessage('❌ 삭제 오류', 'error');\n";
    js = js + "    }\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    return js;
  }

  fn generate_ui_functions() -> string {
    let js = "// UI Functions\n";
    js = js + "function updateUI() {\n";
    js = js + "  updateStats();\n";
    js = js + "  renderPosts();\n";
    js = js + "}\n\n";

    js = js + "function updateStats() {\n";
    js = js + "  document.getElementById('post-count').textContent = appState.posts.length;\n";
    js = js + "  document.getElementById('total-likes').textContent = appState.totalLikes;\n";
    js = js + "  document.getElementById('total-views').textContent = appState.totalViews;\n";
    js = js + "}\n\n";

    js = js + "function renderPosts() {\n";
    js = js + "  const container = document.getElementById('postsContainer');\n";
    js = js + "  if (appState.filteredPosts.length === 0) {\n";
    js = js + "    container.innerHTML = '<div class=\"empty-state\" style=\"text-align:center; padding:60px; color:#999;\">포스트가 없습니다</div>';\n";
    js = js + "    return;\n";
    js = js + "  }\n";
    js = js + "  container.innerHTML = appState.filteredPosts.reverse().map(post => `\n";
    js = js + "    <div class=\"post-card\">\n";
    js = js + "      <div class=\"post-header\">\n";
    js = js + "        <div>\n";
    js = js + "          <h3 class=\"post-title\">${post.title}</h3>\n";
    js = js + "          <p class=\"post-meta\">${post.author} • ${new Date(post.createdAt).toLocaleDateString('ko-KR')}</p>\n";
    js = js + "        </div>\n";
    js = js + "      </div>\n";
    js = js + "      <div><span class=\"post-category\">${post.category}</span></div>\n";
    js = js + "      <p class=\"post-content\">${post.description || post.content.substring(0, 150)}</p>\n";
    js = js + "      <div class=\"post-stats\">\n";
    js = js + "        <div>👁️ ${post.viewCount} 조회</div>\n";
    js = js + "        <div>❤️ ${post.likes} 좋아요</div>\n";
    js = js + "      </div>\n";
    js = js + "      <div class=\"post-actions\">\n";
    js = js + "        <button class=\"post-btn\" onclick=\"openPostModal(${post.id})\" style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; flex: 2;\">📖 전문 보기</button>\n";
    js = js + "        <button class=\"post-btn\" onclick=\"likePost(${post.id})\">❤️ 좋아요</button>\n";
    js = js + "        <button class=\"post-btn post-btn-danger\" onclick=\"deletePost(${post.id})\">🗑️ 삭제</button>\n";
    js = js + "      </div>\n";
    js = js + "    </div>\n";
    js = js + "  `).join('');\n";
    js = js + "}\n\n";

    js = js + "function applyFiltersAndSearch() {\n";
    js = js + "  appState.filteredPosts = appState.posts.filter(post => {\n";
    js = js + "    const matchesFilter = appState.currentFilter === 'all' || post.category === appState.currentFilter;\n";
    js = js + "    const matchesSearch = !appState.currentSearch || post.title.toLowerCase().includes(appState.currentSearch.toLowerCase());\n";
    js = js + "    return matchesFilter && matchesSearch;\n";
    js = js + "  });\n";
    js = js + "}\n\n";

    js = js + "function openPostModal(postId) {\n";
    js = js + "  const post = appState.posts.find(p => p.id === postId);\n";
    js = js + "  if (!post) return;\n";
    js = js + "  \n";
    js = js + "  const tags = post.tags ? post.tags.split(',').map(t => `<span class=\"post-tag\" style=\"display:inline-block; background:#667eea; color:white; padding:4px 10px; border-radius:15px; margin-right:8px; font-size:0.85em;\">${t.trim()}</span>`).join('') : '';\n";
    js = js + "  \n";
    js = js + "  document.getElementById('modalBody').innerHTML = `\n";
    js = js + "    <h1 style=\"color:#667eea; margin-bottom:10px;\">${post.title}</h1>\n";
    js = js + "    <div style=\"color:#999; margin-bottom:20px;\">\n";
    js = js + "      <span>✍️ ${post.author}</span> | \n";
    js = js + "      <span>📅 ${new Date(post.createdAt).toLocaleDateString('ko-KR')}</span> | \n";
    js = js + "      <span>📁 ${post.category}</span>\n";
    js = js + "    </div>\n";
    js = js + "    ${post.description ? `<p style=\"color:#666; font-style:italic; margin-bottom:20px;\">${post.description}</p>` : ''}\n";
    js = js + "    <div style=\"white-space:pre-wrap; word-break:break-word; margin-bottom:30px;\">${post.content}</div>\n";
    js = js + "    ${tags ? `<div style=\"margin-bottom:20px;\"><strong>태그:</strong> ${tags}</div>` : ''}\n";
    js = js + "    <div style=\"border-top:1px solid #eee; padding-top:20px; margin-bottom:20px;\">\n";
    js = js + "      <div>👁️ ${post.viewCount} 조회 | ❤️ ${post.likes} 좋아요</div>\n";
    js = js + "    </div>\n";
    js = js + "    <div style=\"display:flex; gap:10px;\">\n";
    js = js + "      <button class=\"post-btn\" onclick=\"likePost(${post.id})\" style=\"flex:1;\">❤️ 좋아요</button>\n";
    js = js + "      <button class=\"post-btn post-btn-danger\" onclick=\"deletePost(${post.id})\" style=\"flex:1;\">🗑️ 삭제</button>\n";
    js = js + "      <button class=\"post-btn\" onclick=\"closeModal()\" style=\"flex:1;\">✖️ 닫기</button>\n";
    js = js + "    </div>\n";
    js = js + "  `;\n";
    js = js + "  \n";
    js = js + "  document.getElementById('postModal').style.display = 'block';\n";
    js = js + "  viewPost(postId);\n";
    js = js + "}\n\n";

    js = js + "function closeModal() {\n";
    js = js + "  document.getElementById('postModal').style.display = 'none';\n";
    js = js + "}\n\n";

    js = js + "function filterPosts(category) {\n";
    js = js + "  appState.currentFilter = category;\n";
    js = js + "  document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));\n";
    js = js + "  event.target.classList.add('active');\n";
    js = js + "  applyFiltersAndSearch();\n";
    js = js + "  updateUI();\n";
    js = js + "}\n\n";

    js = js + "function searchPosts(query) {\n";
    js = js + "  appState.currentSearch = query;\n";
    js = js + "  applyFiltersAndSearch();\n";
    js = js + "  updateUI();\n";
    js = js + "}\n\n";

    js = js + "function toggleTheme() {\n";
    js = js + "  appState.isDarkTheme = !appState.isDarkTheme;\n";
    js = js + "  document.body.classList.toggle('dark-theme');\n";
    js = js + "  localStorage.setItem('theme', appState.isDarkTheme ? 'dark' : 'light');\n";
    js = js + "}\n\n";

    js = js + "function showMessage(text, type) {\n";
    js = js + "  const msg = document.getElementById('message');\n";
    js = js + "  msg.textContent = text;\n";
    js = js + "  msg.style.color = type === 'success' ? '#51cf66' : '#ff6b6b';\n";
    js = js + "  setTimeout(() => { msg.textContent = ''; }, 3000);\n";
    js = js + "}\n\n";

    return js;
  }

  fn generate_event_handlers() -> string {
    let js = "// Event Handlers\n";
    js = js + "function handleCreatePost(e) {\n";
    js = js + "  e.preventDefault();\n";
    js = js + "  const post = {\n";
    js = js + "    title: document.getElementById('title').value,\n";
    js = js + "    author: document.getElementById('author').value,\n";
    js = js + "    content: document.getElementById('content').value,\n";
    js = js + "    category: document.getElementById('category').value,\n";
    js = js + "    slug: document.getElementById('slug').value,\n";
    js = js + "    description: document.getElementById('description').value,\n";
    js = js + "    tags: document.getElementById('tags').value,\n";
    js = js + "    featured: false\n";
    js = js + "  };\n";
    js = js + "  createPost(post);\n";
    js = js + "}\n\n";

    js = js + "window.onclick = function(e) {\n";
    js = js + "  const modal = document.getElementById('postModal');\n";
    js = js + "  if (e.target === modal) {\n";
    js = js + "    modal.style.display = 'none';\n";
    js = js + "  }\n";
    js = js + "};\n\n";

    return js;
  }

  fn generate_initialization() -> string {
    let js = "// Initialization\n";
    js = js + "document.addEventListener('DOMContentLoaded', () => {\n";
    js = js + "  if (appState.isDarkTheme) {\n";
    js = js + "    document.body.classList.add('dark-theme');\n";
    js = js + "  }\n";
    js = js + "  fetchPosts();\n";
    js = js + "  setInterval(fetchPosts, AUTO_REFRESH);\n";
    js = js + "});\n";

    return js;
  }

  // Helper function
  fn to_string(n: i32) -> string {
    // Simple number to string (프리랭에서 제공 예상)
    match n {
      5000 => "5000",
      _ => "5000"
    }
  }
}

toolUseResult.content:
/**
 * FreeLang Frontend Generator
 * 프리랭으로 완전한 블로그 프론트엔드 생성
 *
 * 목표:
 * 1. HTML 완전 생성 (구조)
 * 2. CSS 완전 생성 (스타일)
 * 3. JavaScript 완전 생성 (동작)
 * 4. API 통합 (백엔드 연결)
 * 5. 상태 관리 (클라이언트 사이드)
 */

module FrontendGenerator {

  // ============================================================================
  // Part 1: Configuration & Types
  // ============================================================================

  struct BlogConfig {
    title: string,
    api_url: string,
    port: i32,
    theme: string,
    auto_refresh: i32,  // milliseconds
  }

  struct UIState {
    current_page: i32,
    posts_per_page: i32,
    theme: string,
    search_query: string,
    selected_category: string,
  }

  // ============================================================================
  // Part 2: HTML Generator
  // ============================================================================

  pub fn generate_complete_html(config: BlogConfig) -> string {
    let html = "<!DOCTYPE html>\n";
    html = html + "<html lang=\"ko\">\n";
    html = html + generate_head(config);
    html = html + generate_body(config);
    html = html + "</html>\n";
    return html;
  }

  fn generate_head(config: BlogConfig) -> string {
    let head = "<head>\n";
    head = head + "  <meta charset=\"UTF-8\">\n";
    head = head + "  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n";
    head = head + "  <title>" + config.title + "</title>\n";
    head = head + "  <style>\n";
    head = head + generate_complete_css(config);
    head = head + "  </style>\n";
    head = head + "</head>\n";
    return head;
  }

  fn generate_body(config: BlogConfig) -> string {
    let body = "<body>\n";
    body = body + "  <div id=\"app\" class=\"container\">\n";
    body = body + generate_navbar(config);
    body = body + generate_hero(config);
    body = body + generate_create_post_section(config);
    body = body + generate_filters(config);
    body = body + generate_posts_container();
    body = body + generate_modals();
    body = body + "  </div>\n";
    body = body + "  <script>\n";
    body = body + generate_complete_javascript(config);
    body = body + "  </script>\n";
    body = body + "</body>\n";
    return body;
  }

  fn generate_navbar(config: BlogConfig) -> string {
    let nav = "    <nav class=\"navbar\">\n";
    nav = nav + "      <div class=\"navbar-brand\">\n";
    nav = nav + "        <h1>📝 " + config.title + "</h1>\n";
    nav = nav + "        <p class=\"subtitle\">FreeLang으로 만든 완전한 블로그</p>\n";
    nav = nav + "      </div>\n";
    nav = nav + "      <div class=\"navbar-menu\">\n";
    nav = nav + "        <button class=\"theme-toggle\" onclick=\"toggleTheme()\">🌙</button>\n";
    nav = nav + "        <input type=\"text\" id=\"search\" placeholder=\"검색...\" onkeyup=\"searchPosts(this.value)\" class=\"search-box\">\n";
    nav = nav + "      </div>\n";
    nav = nav + "    </nav>\n";
    return nav;
  }

  fn generate_hero(config: BlogConfig) -> string {
    let hero = "    <section class=\"hero\">\n";
    hero = hero + "      <h2>FreeLang Blog Engine</h2>\n";
    hero = hero + "      <p>순수 프리랭으로 구현된 제로 디펜던시 블로그</p>\n";
    hero = hero + "      <div class=\"stats\">\n";
    hero = hero + "        <div class=\"stat\">📚 <span id=\"post-count\">0</span> 포스트</div>\n";
    hero = hero + "        <div class=\"stat\">❤️ <span id=\"total-likes\">0</span> 좋아요</div>\n";
    hero = hero + "        <div class=\"stat\">👁️ <span id=\"total-views\">0</span> 조회</div>\n";
    hero = hero + "      </div>\n";
    hero = hero + "    </section>\n";
    return hero;
  }

  fn generate_create_post_section(config: BlogConfig) -> string {
    let form = "    <section class=\"create-post\">\n";
    form = form + "      <h2>✍️ 새 포스트 작성</h2>\n";
    form = form + "      <form id=\"postForm\" onsubmit=\"handleCreatePost(event)\">\n";
    form = form + "        <div class=\"form-row\">\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"title\">제목</label>\n";
    form = form + "            <input type=\"text\" id=\"title\" required placeholder=\"포스트 제목\">\n";
    form = form + "          </div>\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"author\">작성자</label>\n";
    form = form + "            <input type=\"text\" id=\"author\" required placeholder=\"이름\">\n";
    form = form + "          </div>\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-row\">\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"category\">카테고리</label>\n";
    form = form + "            <input type=\"text\" id=\"category\" required placeholder=\"기술, 일상, ...\">\n";
    form = form + "          </div>\n";
    form = form + "          <div class=\"form-group\">\n";
    form = form + "            <label for=\"slug\">슬러그</label>\n";
    form = form + "            <input type=\"text\" id=\"slug\" required placeholder=\"url-friendly\">\n";
    form = form + "          </div>\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-group\">\n";
    form = form + "          <label for=\"description\">설명</label>\n";
    form = form + "          <input type=\"text\" id=\"description\" placeholder=\"포스트 한줄 설명\">\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-group\">\n";
    form = form + "          <label for=\"content\">내용</label>\n";
    form = form + "          <textarea id=\"content\" required placeholder=\"포스트 내용...\" rows=\"8\"></textarea>\n";
    form = form + "        </div>\n";
    form = form + "        <div class=\"form-group\">\n";
    form = form + "          <label for=\"tags\">태그 (쉼표 구분)</label>\n";
    form = form + "          <input type=\"text\" id=\"tags\" placeholder=\"tag1, tag2, tag3\">\n";
    form = form + "        </div>\n";
    form = form + "        <button type=\"submit\" class=\"btn-primary\">📤 포스트 작성</button>\n";
    form = form + "      </form>\n";
    form = form + "      <div id=\"message\" class=\"message\"></div>\n";
    form = form + "    </section>\n";
    return form;
  }

  fn generate_filters(config: BlogConfig) -> string {
    let filters = "    <section class=\"filters\">\n";
