  fn generate_complete_javascript(config: BlogConfig) -> string {
    let js = "// FreeLang Generated Blog Frontend\n";
    js = js + "const API_URL = '" + config.api_url + "/api';\n";
    js = js + "const AUTO_REFRESH = " + to_string(config.auto_refresh) + ";\n\n";

    js = js + generate_state_management();
    js = js + generate_api_functions();
    js = js + generate_ui_functions();
    js = js + generate_event_handlers();
    js = js + generate_initialization();

    return js;
  }

  fn generate_state_management() -> string {
    let js = "// State Management\n";
    js = js + "let appState = {\n";
    js = js + "  posts: [],\n";
    js = js + "  filteredPosts: [],\n";
    js = js + "  currentFilter: 'all',\n";
    js = js + "  currentSearch: '',\n";
    js = js + "  isDarkTheme: localStorage.getItem('theme') === 'dark',\n";
    js = js + "  totalLikes: 0,\n";
    js = js + "  totalViews: 0\n";
    js = js + "};\n\n";

    return js;
  }

  fn generate_api_functions() -> string {
    let js = "// API Functions\n";
    js = js + "async function fetchPosts() {\n";
    js = js + "  try {\n";
    js = js + "    const res = await fetch(API_URL + '/blogs');\n";
    js = js + "    const data = await res.json();\n";
    js = js + "    appState.posts = data.data || [];\n";
    js = js + "    appState.totalLikes = appState.posts.reduce((sum, p) => sum + (p.likes || 0), 0);\n";
    js = js + "    appState.totalViews = appState.posts.reduce((sum, p) => sum + (p.viewCount || 0), 0);\n";
    js = js + "    applyFiltersAndSearch();\n";
    js = js + "    updateUI();\n";
    js = js + "  } catch (err) {\n";
    js = js + "    console.error('포스트 로드 오류:', err);\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function createPost(postData) {\n";
    js = js + "  try {\n";
    js = js + "    const res = await fetch(API_URL + '/blogs', {\n";
    js = js + "      method: 'POST',\n";
    js = js + "      headers: { 'Content-Type': 'application/json' },\n";
    js = js + "      body: JSON.stringify(postData)\n";
    js = js + "    });\n";
    js = js + "    if (res.ok) {\n";
    js = js + "      showMessage('✅ 포스트 작성됨!', 'success');\n";
    js = js + "      document.getElementById('postForm').reset();\n";
    js = js + "      fetchPosts();\n";
    js = js + "    } else {\n";
    js = js + "      showMessage('❌ 포스트 작성 실패', 'error');\n";
    js = js + "    }\n";
    js = js + "  } catch (err) {\n";
    js = js + "    showMessage('❌ 오류: ' + err.message, 'error');\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function likePost(postId) {\n";
    js = js + "  try {\n";
    js = js + "    await fetch(API_URL + '/blogs/' + postId + '/like', { method: 'POST' });\n";
    js = js + "    fetchPosts();\n";
    js = js + "  } catch (err) {\n";
    js = js + "    console.error('좋아요 오류:', err);\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function viewPost(postId) {\n";
    js = js + "  try {\n";
    js = js + "    await fetch(API_URL + '/blogs/' + postId + '/view', { method: 'POST' });\n";
    js = js + "    fetchPosts();\n";
    js = js + "  } catch (err) {\n";
    js = js + "    console.error('조회수 증가 오류:', err);\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    js = js + "async function deletePost(postId) {\n";
    js = js + "  if (confirm('정말 삭제하시겠습니까?')) {\n";
    js = js + "    try {\n";
    js = js + "      await fetch(API_URL + '/blogs/' + postId, { method: 'DELETE' });\n";
    js = js + "      showMessage('✅ 포스트 삭제됨!', 'success');\n";
    js = js + "      closeModal();\n";
    js = js + "      fetchPosts();\n";
    js = js + "    } catch (err) {\n";
    js = js + "      showMessage('❌ 삭제 오류', 'error');\n";
    js = js + "    }\n";
    js = js + "  }\n";
    js = js + "}\n\n";

    return js;
  }

  fn generate_ui_functions() -> string {
    let js = "// UI Functions\n";
    js = js + "function updateUI() {\n";
    js = js + "  updateStats();\n";
    js = js + "  renderPosts();\n";
    js = js + "}\n\n";

    js = js + "function updateStats() {\n";
    js = js + "  document.getElementById('post-count').textContent = appState.posts.length;\n";
    js = js + "  document.getElementById('total-likes').textContent = appState.totalLikes;\n";
    js = js + "  document.getElementById('total-views').textContent = appState.totalViews;\n";
    js = js + "}\n\n";

    js = js + "function renderPosts() {\n";
    js = js + "  const container = document.getElementById('postsContainer');\n";
    js = js + "  if (appState.filteredPosts.length === 0) {\n";
    js = js + "    container.innerHTML = '<div class=\"empty-state\" style=\"text-align:center; padding:60px; color:#999;\">포스트가 없습니다</div>';\n";
    js = js + "    return;\n";
    js = js + "  }\n";
    js = js + "  container.innerHTML = appState.filteredPosts.reverse().map(post => `\n";
    js = js + "    <div class=\"post-card\">\n";
    js = js + "      <div class=\"post-header\">\n";
    js = js + "        <div>\n";
    js = js + "          <h3 class=\"post-title\">${post.title}</h3>\n";
    js = js + "          <p class=\"post-meta\">${post.author} • ${new Date(post.createdAt).toLocaleDateString('ko-KR')}</p>\n";
    js = js + "        </div>\n";
    js = js + "      </div>\n";
    js = js + "      <div><span class=\"post-category\">${post.category}</span></div>\n";
    js = js + "      <p class=\"post-content\">${post.description || post.content.substring(0, 150)}</p>\n";
    js = js + "      <div class=\"post-stats\">\n";
    js = js + "        <div>👁️ ${post.viewCount} 조회</div>\n";
    js = js + "        <div>❤️ ${post.likes} 좋아요</div>\n";
    js = js + "      </div>\n";
    js = js + "      <div class=\"post-actions\">\n";
    js = js + "        <button class=\"post-btn\" onclick=\"openPostModal(${post.id})\" style=\"background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; flex: 2;\">📖 전문 보기</button>\n";
    js = js + "        <button class=\"post-btn\" onclick=\"likePost(${post.id})\">❤️ 좋아요</button>\n";
    js = js + "        <button class=\"post-btn post-btn-danger\" onclick=\"deletePost(${post.id})\">🗑️ 삭제</button>\n";
    js = js + "      </div>\n";
    js = js + "    </div>\n";
    js = js + "  `).join('');\n";
    js = js + "}\n\n";

    js = js + "function applyFiltersAndSearch() {\n";
    js = js + "  appState.filteredPosts = appState.posts.filter(post => {\n";
    js = js + "    const matchesFilter = appState.currentFilter === 'all' || post.category === appState.currentFilter;\n";
    js = js + "    const matchesSearch = !appState.currentSearch || post.title.toLowerCase().includes(appState.currentSearch.toLowerCase());\n";
    js = js + "    return matchesFilter && matchesSearch;\n";
    js = js + "  });\n";
    js = js + "}\n\n";

    js = js + "function openPostModal(postId) {\n";
    js = js + "  const post = appState.posts.find(p => p.id === postId);\n";
    js = js + "  if (!post) return;\n";
    js = js + "  \n";
    js = js + "  const tags = post.tags ? post.tags.split(',').map(t => `<span class=\"post-tag\" style=\"display:inline-block; background:#667eea; color:white; padding:4px 10px; border-radius:15px; margin-right:8px; font-size:0.85em;\">${t.trim()}</span>`).join('') : '';\n";
    js = js + "  \n";
    js = js + "  document.getElementById('modalBody').innerHTML = `\n";
    js = js + "    <h1 style=\"color:#667eea; margin-bottom:10px;\">${post.title}</h1>\n";
    js = js + "    <div style=\"color:#999; margin-bottom:20px;\">\n";
    js = js + "      <span>✍️ ${post.author}</span> | \n";
    js = js + "      <span>📅 ${new Date(post.createdAt).toLocaleDateString('ko-KR')}</span> | \n";
    js = js + "      <span>📁 ${post.category}</span>\n";
    js = js + "    </div>\n";
    js = js + "    ${post.description ? `<p style=\"color:#666; font-style:italic; margin-bottom:20px;\">${post.description}</p>` : ''}\n";
    js = js + "    <div style=\"white-space:pre-wrap; word-break:break-word; margin-bottom:30px;\">${post.content}</div>\n";
    js = js + "    ${tags ? `<div style=\"margin-bottom:20px;\"><strong>태그:</strong> ${tags}</div>` : ''}\n";
    js = js + "    <div style=\"border-top:1px solid #eee; padding-top:20px; margin-bottom:20px;\">\n";
    js = js + "      <div>👁️ ${post.viewCount} 조회 | ❤️ ${post.likes} 좋아요</div>\n";
    js = js + "    </div>\n";
    js = js + "    <div style=\"display:flex; gap:10px;\">\n";
    js = js + "      <button class=\"post-btn\" onclick=\"likePost(${post.id})\" style=\"flex:1;\">❤️ 좋아요</button>\n";
    js = js + "      <button class=\"post-btn post-btn-danger\" onclick=\"deletePost(${post.id})\" style=\"flex:1;\">🗑️ 삭제</button>\n";
    js = js + "      <button class=\"post-btn\" onclick=\"closeModal()\" style=\"flex:1;\">✖️ 닫기</button>\n";
    js = js + "    </div>\n";
    js = js + "  `;\n";
    js = js + "  \n";
    js = js + "  document.getElementById('postModal').style.display = 'block';\n";
    js = js + "  viewPost(postId);\n";
    js = js + "}\n\n";

    js = js + "function closeModal() {\n";
    js = js + "  document.getElementById('postModal').style.display = 'none';\n";
    js = js + "}\n\n";

    js = js + "function filterPosts(category) {\n";
    js = js + "  appState.currentFilter = category;\n";
    js = js + "  document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));\n";
    js = js + "  event.target.classList.add('active');\n";
    js = js + "  applyFiltersAndSearch();\n";
    js = js + "  updateUI();\n";
    js = js + "}\n\n";

    js = js + "function searchPosts(query) {\n";
    js = js + "  appState.currentSearch = query;\n";
    js = js + "  applyFiltersAndSearch();\n";
    js = js + "  updateUI();\n";
    js = js + "}\n\n";

    js = js + "function toggleTheme() {\n";
    js = js + "  appState.isDarkTheme = !appState.isDarkTheme;\n";
    js = js + "  document.body.classList.toggle('dark-theme');\n";
    js = js + "  localStorage.setItem('theme', appState.isDarkTheme ? 'dark' : 'light');\n";
    js = js + "}\n\n";

    js = js + "function showMessage(text, type) {\n";
    js = js + "  const msg = document.getElementById('message');\n";
    js = js + "  msg.textContent = text;\n";
    js = js + "  msg.style.color = type === 'success' ? '#51cf66' : '#ff6b6b';\n";
    js = js + "  setTimeout(() => { msg.textContent = ''; }, 3000);\n";
    js = js + "}\n\n";

    return js;
  }

  fn generate_event_handlers() -> string {
    let js = "// Event Handlers\n";
    js = js + "function handleCreatePost(e) {\n";
    js = js + "  e.preventDefault();\n";
    js = js + "  const post = {\n";
    js = js + "    title: document.getElementById('title').value,\n";
    js = js + "    author: document.getElementById('author').value,\n";
    js = js + "    content: document.getElementById('content').value,\n";
    js = js + "    category: document.getElementById('category').value,\n";
    js = js + "    slug: document.getElementById('slug').value,\n";
    js = js + "    description: document.getElementById('description').value,\n";
    js = js + "    tags: document.getElementById('tags').value,\n";
    js = js + "    featured: false\n";
    js = js + "  };\n";
    js = js + "  createPost(post);\n";
    js = js + "}\n\n";

    js = js + "window.onclick = function(e) {\n";
    js = js + "  const modal = document.getElementById('postModal');\n";
    js = js + "  if (e.target === modal) {\n";
    js = js + "    modal.style.display = 'none';\n";
    js = js + "  }\n";
    js = js + "};\n\n";

    return js;
  }

  fn generate_initialization() -> string {
    let js = "// Initialization\n";
    js = js + "document.addEventListener('DOMContentLoaded', () => {\n";
    js = js + "  if (appState.isDarkTheme) {\n";
    js = js + "    document.body.classList.add('dark-theme');\n";
    js = js + "  }\n";
    js = js + "  fetchPosts();\n";
    js = js + "  setInterval(fetchPosts, AUTO_REFRESH);\n";
    js = js + "});\n";

    return js;
  }

  // Helper function
  fn to_string(n: i32) -> string {
    // Simple number to string (프리랭에서 제공 예상)
    match n {
      5000 => "5000",
      _ => "5000"
    }
  }
}

input.content:
/**
 * FreeLang Frontend Generator Executor
 * frontend-generator.fl을 실행하여 완전한 HTML 생성
 *
 * 이것은 프리랭 컴파일러를 통해 실행될 코드입니다.
 * 현재는 Node.js로 시뮬레이션합니다 (프리랭 → JS 트랜스파일)
 */

// FreeLang을 JavaScript로 트랜스파일한 프론트엔드 생성기
const FrontendGenerator = {

  // HTML 생성
  generateCompleteHtml(config) {
    let html = '<!DOCTYPE html>\n';
    html += '<html lang="ko">\n';
    html += this.generateHead(config);
    html += this.generateBody(config);
    html += '</html>\n';
    return html;
  },

  generateHead(config) {
    return `<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${config.title}</title>
  <style>
${this.generateCompleteCss(config)}
  </style>
</head>
`;
  },

  generateBody(config) {
    return `<body>
  <div id="app" class="container">
${this.generateNavbar(config)}
${this.generateHero(config)}
${this.generateCreatePostSection(config)}
${this.generateFilters(config)}
${this.generatePostsContainer()}
${this.generateModals()}
  </div>
  <script>
${this.generateCompleteJavascript(config)}
  </script>
</body>
`;
  },

  generateNavbar(config) {
    return `    <nav class="navbar">
      <div class="navbar-brand">
        <h1>📝 ${config.title}</h1>
        <p class="subtitle">FreeLang으로 만든 완전한 블로그</p>
      </div>
      <div class="navbar-menu">
        <button class="theme-toggle" onclick="toggleTheme()">🌙</button>
        <input type="text" id="search" placeholder="검색..." onkeyup="searchPosts(this.value)" class="search-box">
      </div>
    </nav>
`;
  },

  generateHero(config) {
    return `    <section class="hero">
      <h2>FreeLang Blog Engine</h2>
      <p>순수 프리랭으로 구현된 제로 디펜던시 블로그</p>
      <div class="stats">
        <div class="stat">📚 <span id="post-count">0</span> 포스트</div>
        <div class="stat">❤️ <span id="total-likes">0</span> 좋아요</div>
        <div class="stat">👁️ <span id="total-views">0</span> 조회</div>
      </div>
    </section>
`;
  },

  generateCreatePostSection(config) {
    return `    <section class="create-post">
      <h2>✍️ 새 포스트 작성</h2>
      <form id="postForm" onsubmit="handleCreatePost(event)">
        <div class="form-row">
          <div class="form-group">
            <label for="title">제목</label>
            <input type="text" id="title" required placeholder="포스트 제목">
          </div>
          <div class="form-group">
            <label for="author">작성자</label>
            <input type="text" id="author" required placeholder="이름">
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label for="category">카테고리</label>
            <input type="text" id="category" required placeholder="기술, 일상, ...">
          </div>
          <div class="form-group">
            <label for="slug">슬러그</label>
            <input type="text" id="slug" required placeholder="url-friendly">
          </div>
        </div>
        <div class="form-group">
          <label for="description">설명</label>
          <input type="text" id="description" placeholder="포스트 한줄 설명">
        </div>
        <div class="form-group">
          <label for="content">내용</label>
          <textarea id="content" required placeholder="포스트 내용..." rows="8"></textarea>
        </div>
        <div class="form-group">
          <label for="tags">태그 (쉼표 구분)</label>
          <input type="text" id="tags" placeholder="tag1, tag2, tag3">
        </div>
        <button type="submit" class="btn-primary">📤 포스트 작성</button>
      </form>
      <div id="message" class="message"></div>
    </section>
`;
  },

  generateFilters(config) {
    return `    <section class="filters">
      <button class="filter-btn active" onclick="filterPosts('all')">📌 전체</button>
      <button class="filter-btn" onclick="filterPosts('Achievement')">🏆 성과</button>
      <button class="filter-btn" onclick="filterPosts('Technical')">⚙️ 기술</button>
      <button class="filter-btn" onclick="filterPosts('Architecture')">🏗️ 아키텍처</button>
    </section>
`;
  },

  generatePostsContainer() {
    return '    <section id="postsContainer" class="posts-container"></section>\n';
  },

  generateModals() {
    return `    <div id="postModal" class="modal">
      <div class="modal-content">
        <span class="modal-close" onclick="closeModal()">&times;</span>
        <div id="modalBody"></div>
      </div>
    </div>
`;
  },

  // CSS 동적 생성
  generateCompleteCss(config) {
    let css = '';
    css += this.generateBaseStyles();
    css += this.generateNavbarStyles();
    css += this.generateHeroStyles();
    css += this.generateFormStyles();
    css += this.generateFilterStyles();
    css += this.generatePostCardStyles();
    css += this.generateModalStyles();
    css += this.generateThemeStyles();
    css += this.generateResponsiveStyles();
    return css;
  },

  generateBaseStyles() {
    return `* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: #333;
  min-height: 100vh;
  transition: background 0.3s ease;
}

body.dark-theme {
  background: linear-gradient(135deg, #2d3436 0%, #636e72 100%);
  color: #fff;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

`;
  },

  generateNavbarStyles() {
    return `.navbar {
  background: rgba(255, 255, 255, 0.95);
  padding: 20px 30px;
  border-radius: 10px;
  margin-bottom: 30px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.navbar-brand h1 {
  color: #667eea;
  font-size: 1.8em;
}

.subtitle {
  color: #666;
  font-size: 0.9em;
}

.navbar-menu {
  display: flex;
  gap: 15px;
  align-items: center;
}

.search-box {
  padding: 10px 15px;
  border: 2px solid #eee;
  border-radius: 5px;
  width: 250px;
}

.theme-toggle {
  background: #f0f0f0;
  border: none;
  padding: 8px 12px;
  border-radius: 5px;
  cursor: pointer;
  font-size: 1.2em;
}

`;
  },

  generateHeroStyles() {
    return `.hero {
  background: rgba(255, 255, 255, 0.95);
  padding: 60px;
  border-radius: 10px;
  text-align: center;
  margin-bottom: 30px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.hero h2 {
  color: #667eea;
  font-size: 2.5em;
  margin-bottom: 10px;
}

.hero p {
  color: #666;
  font-size: 1.1em;
  margin-bottom: 30px;
}

.stats {
  display: flex;
  justify-content: center;
  gap: 40px;
}

.stat {
  font-size: 1.2em;
  color: #333;
}

`;
  },

  generateFormStyles() {
    return `.create-post {
  background: rgba(255, 255, 255, 0.95);
  padding: 30px;
  border-radius: 10px;
  margin-bottom: 30px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

.create-post h2 {
  color: #333;
  margin-bottom: 20px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 20px;
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
  color: #333;
}

.form-group input,
.form-group textarea {
  width: 100%;
  padding: 12px;
  border: 2px solid #eee;
  border-radius: 5px;
  font-family: inherit;
  font-size: 1em;
  transition: border-color 0.3s;
}

.form-group input:focus,
.form-group textarea:focus {
  outline: none;
  border-color: #667eea;
}

.btn-primary {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 12px 30px;
  border: none;
  border-radius: 5px;
  font-size: 1em;
  cursor: pointer;
  transition: transform 0.2s;
}

.btn-primary:hover {
  transform: translateY(-2px);
}

`;
  },

  generateFilterStyles() {
    return `.filters {
  display: flex;
  gap: 10px;
  margin-bottom: 30px;
  justify-content: center;
  flex-wrap: wrap;
}

.filter-btn {
  padding: 10px 20px;
  border: 2px solid #667eea;
  background: white;
  color: #667eea;
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.3s;
}

.filter-btn.active {
  background: #667eea;
  color: white;
}

`;
  },

  generatePostCardStyles() {
    return `.posts-container {
  display: grid;
  gap: 20px;
}

.post-card {
  background: rgba(255, 255, 255, 0.95);
  padding: 25px;
  border-radius: 10px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
  transition: transform 0.3s, box-shadow 0.3s;
}

.post-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 40px rgba(0,0,0,0.15);
}

.post-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 15px;
}

.post-title {
  color: #333;
  font-size: 1.5em;
  margin-bottom: 8px;
}

.post-meta {
  color: #999;
  font-size: 0.9em;
}

.post-category {
  display: inline-block;
  background: #667eea;
  color: white;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 0.85em;
  margin-bottom: 15px;
}

.post-content {
  color: #555;
  line-height: 1.6;
  margin-bottom: 15px;
}

.post-stats {
  display: flex;
  gap: 20px;
  margin-bottom: 15px;
  font-size: 0.95em;
  color: #666;
}

.post-actions {
  display: flex;
  gap: 10px;
}

.post-btn {
  padding: 8px 15px;
  border: none;
  background: #f0f0f0;
  color: #333;
  border-radius: 5px;
  cursor: pointer;
  transition: background 0.3s;
}

.post-btn:hover {
  background: #e0e0e0;
}

.post-btn-danger {
  background: #ff6b6b;
  color: white;
}

.post-btn-danger:hover {
  background: #ff5252;
}

`;
  },

  generateModalStyles() {
    return `.modal {
  display: none;
  position: fixed;
  z-index: 1000;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0,0,0,0.8);
}

.modal-content {
  background: white;
  margin: 5% auto;
  padding: 40px;
  border-radius: 10px;
  width: 90%;
  max-width: 900px;
  max-height: 80vh;
  overflow-y: auto;
  box-shadow: 0 20px 60px rgba(0,0,0,0.3);
}

.modal-close {
  float: right;
  font-size: 2em;
  font-weight: bold;
  cursor: pointer;
  color: #999;
}

.modal-close:hover {
  color: #333;
}

`;
  },

  generateThemeStyles() {
    return `body.dark-theme .navbar {
  background: rgba(45, 52, 54, 0.95);
}

body.dark-theme .navbar-brand h1 {
  color: #667eea;
}

body.dark-theme .hero,
body.dark-theme .create-post,
body.dark-theme .post-card {
  background: rgba(45, 52, 54, 0.95);
  color: #fff;
}

body.dark-theme .post-card {
  border-left: 4px solid #667eea;
}

body.dark-theme .form-group input,
body.dark-theme .form-group textarea {
  background: #333;
  color: #fff;
  border-color: #555;
}

`;
  },

  generateResponsiveStyles() {
    return `@media (max-width: 768px) {
  .form-row {
    grid-template-columns: 1fr;
  }

  .navbar {
    flex-direction: column;
    gap: 15px;
  }

  .navbar-menu {
    flex-direction: column;
    width: 100%;
  }

  .search-box {
    width: 100%;
  }

  .post-header {
    flex-direction: column;
  }
}

`;
  },

  // JavaScript 생성
  generateCompleteJavascript(config) {
    return `const API_URL = '${config.api_url}/api';
const AUTO_REFRESH = ${config.auto_refresh};

// State Management
let appState = {
  posts: [],
  filteredPosts: [],
  currentFilter: 'all',
  currentSearch: '',
  isDarkTheme: localStorage.getItem('theme') === 'dark',
  totalLikes: 0,
  totalViews: 0
};

// API Functions
async function fetchPosts() {
  try {
    const res = await fetch(API_URL + '/blogs');
    const data = await res.json();
    appState.posts = data.data || [];
    appState.totalLikes = appState.posts.reduce((sum, p) => sum + (p.likes || 0), 0);
    appState.totalViews = appState.posts.reduce((sum, p) => sum + (p.viewCount || 0), 0);
    applyFiltersAndSearch();
    updateUI();
  } catch (err) {
    console.error('포스트 로드 오류:', err);
  }
}

async function createPost(postData) {
  try {
    const res = await fetch(API_URL + '/blogs', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(postData)
    });
    if (res.ok) {
      showMessage('✅ 포스트 작성됨!', 'success');
      document.getElementById('postForm').reset();
      fetchPosts();
    } else {
      showMessage('❌ 포스트 작성 실패', 'error');
    }
  } catch (err) {
    showMessage('❌ 오류: ' + err.message, 'error');
  }
}

async function likePost(postId) {
  try {
    await fetch(API_URL + '/blogs/' + postId + '/like', { method: 'POST' });
    fetchPosts();
  } catch (err) {
    console.error('좋아요 오류:', err);
  }
}

async function viewPost(postId) {
  try {
    await fetch(API_URL + '/blogs/' + postId + '/view', { method: 'POST' });
    fetchPosts();
  } catch (err) {
    console.error('조회수 증가 오류:', err);
  }
}

async function deletePost(postId) {
  if (confirm('정말 삭제하시겠습니까?')) {
    try {
      await fetch(API_URL + '/blogs/' + postId, { method: 'DELETE' });
      showMessage('✅ 포스트 삭제됨!', 'success');
      closeModal();
      fetchPosts();
    } catch (err) {
      showMessage('❌ 삭제 오류', 'error');
    }
  }
}

// UI Functions
function updateUI() {
  updateStats();
  renderPosts();
}

function updateStats() {
  document.getElementById('post-count').textContent = appState.posts.length;
  document.getElementById('total-likes').textContent = appState.totalLikes;
  document.getElementById('total-views').textContent = appState.totalViews;
}

function renderPosts() {
  const container = document.getElementById('postsContainer');
  if (appState.filteredPosts.length === 0) {
    container.innerHTML = '<div class="empty-state" style="text-align:center; padding:60px; color:#999;">포스트가 없습니다</div>';
    return;
  }
  container.innerHTML = appState.filteredPosts.reverse().map(post => \`
    <div class="post-card">
      <div class="post-header">
        <div>
          <h3 class="post-title">\${post.title}</h3>
          <p class="post-meta">\${post.author} • \${new Date(post.createdAt).toLocaleDateString('ko-KR')}</p>
        </div>
      </div>
      <div><span class="post-category">\${post.category}</span></div>
      <p class="post-content">\${post.description || post.content.substring(0, 150)}</p>
      <div class="post-stats">
        <div>👁️ \${post.viewCount} 조회</div>
        <div>❤️ \${post.likes} 좋아요</div>
      </div>
      <div class="post-actions">
        <button class="post-btn" onclick="openPostModal(\${post.id})" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; flex: 2;">📖 전문 보기</button>
        <button class="post-btn" onclick="likePost(\${post.id})">❤️ 좋아요</button>
        <button class="post-btn post-btn-danger" onclick="deletePost(\${post.id})">🗑️ 삭제</button>
      </div>
    </div>
  \`).join('');
}

function applyFiltersAndSearch() {
  appState.filteredPosts = appState.posts.filter(post => {
    const matchesFilter = appState.currentFilter === 'all' || post.category === appState.currentFilter;
    const matchesSearch = !appState.currentSearch || post.title.toLowerCase().includes(appState.currentSearch.toLowerCase());
    return matchesFilter && matchesSearch;
  });
}

function openPostModal(postId) {
  const post = appState.posts.find(p => p.id === postId);
  if (!post) return;

  const tags = post.tags ? post.tags.split(',').map(t => \`<span class="post-tag" style="display:inline-block; background:#667eea; color:white; padding:4px 10px; border-radius:15px; margin-right:8px; font-size:0.85em;">\${t.trim()}</span>\`).join('') : '';

  document.getElementById('modalBody').innerHTML = \`
    <h1 style="color:#667eea; margin-bottom:10px;">\${post.title}</h1>
    <div style="color:#999; margin-bottom:20px;">
      <span>✍️ \${post.author}</span> |
      <span>📅 \${new Date(post.createdAt).toLocaleDateString('ko-KR')}</span> |
      <span>📁 \${post.category}</span>
    </div>
    \${post.description ? \`<p style="color:#666; font-style:italic; margin-bottom:20px;">\${post.description}</p>\` : ''}
    <div style="white-space:pre-wrap; word-break:break-word; margin-bottom:30px;">\${post.content}</div>
    \${tags ? \`<div style="margin-bottom:20px;"><strong>태그:</strong> \${tags}</div>\` : ''}
    <div style="border-top:1px solid #eee; padding-top:20px; margin-bottom:20px;">
      <div>👁️ \${post.viewCount} 조회 | ❤️ \${post.likes} 좋아요</div>
    </div>
    <div style="display:flex; gap:10px;">
      <button class="post-btn" onclick="likePost(\${post.id})" style="flex:1;">❤️ 좋아요</button>
      <button class="post-btn post-btn-danger" onclick="deletePost(\${post.id})" style="flex:1;">🗑️ 삭제</button>
      <button class="post-btn" onclick="closeModal()" style="flex:1;">✖️ 닫기</button>
    </div>
  \`;

  document.getElementById('postModal').style.display = 'block';
  viewPost(postId);
}

function closeModal() {
  document.getElementById('postModal').style.display = 'none';
}

function filterPosts(category) {
  appState.currentFilter = category;
  document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));
  event.target.classList.add('active');
  applyFiltersAndSearch();
  updateUI();
}

function searchPosts(query) {
  appState.currentSearch = query;
  applyFiltersAndSearch();
  updateUI();
}

function toggleTheme() {
  appState.isDarkTheme = !appState.isDarkTheme;
  document.body.classList.toggle('dark-theme');
  localStorage.setItem('theme', appState.isDarkTheme ? 'dark' : 'light');
}

function showMessage(text, type) {
  const msg = document.getElementById('message');
  msg.textContent = text;
  msg.style.color = type === 'success' ? '#51cf66' : '#ff6b6b';
  setTimeout(() => { msg.textContent = ''; }, 3000);
}

// Event Handlers
function handleCreatePost(e) {
  e.preventDefault();
  const post = {
    title: document.getElementById('title').value,
    author: document.getElementById('author').value,
    content: document.getElementById('content').value,
    category: document.getElementById('category').value,
    slug: document.getElementById('slug').value,
    description: document.getElementById('description').value,
    tags: document.getElementById('tags').value,
    featured: false
  };
  createPost(post);
}

window.onclick = function(e) {
  const modal = document.getElementById('postModal');
  if (e.target === modal) {
    modal.style.display = 'none';
  }
};

// Initialization
document.addEventListener('DOMContentLoaded', () => {
  if (appState.isDarkTheme) {
    document.body.classList.add('dark-theme');
  }
  fetchPosts();
  setInterval(fetchPosts, AUTO_REFRESH);
});
`;
  }
};

